const body = $json.body || {};
const headers = $json.headers || {};
const expectedSecret = 'O2LwUFK2HvTDhG53';
const senderPhoneNumberId = '1203164092890708';
const receivedSecret = String(headers['x-lms-whatsapp-secret'] || headers['X-Lms-Whatsapp-Secret'] || '').trim();

if (expectedSecret && receivedSecret !== expectedSecret) {
  throw new Error('Invalid LMS WhatsApp forwarding secret');
}

const normalizeWhatsAppNumber = (value) => {
  const digits = String(value || '').replace(/\D/g, '');
  return digits.length === 10 ? '91' + digits : digits;
};

const rawRecipients = Array.isArray(body.recipients) && body.recipients.length ? body.recipients : body.to ? [body.to] : [];
const recipients = [...new Set(rawRecipients.map(normalizeWhatsAppNumber).filter(Boolean))];
if (!recipients.length) throw new Error('No WhatsApp recipients provided');

const rawBodyParameters = Array.isArray(body.bodyParameters) ? body.bodyParameters : Array.isArray(body.templateVariables) ? body.templateVariables : [];
const bodyParameters = rawBodyParameters.map((value) => String(value || '').trim().slice(0, 1024)).filter(Boolean);

const templateName = String(body.templateName || body.template_name || '').trim();
const language = String(body.language || body.language_code || 'en_US').trim();
if (!templateName) throw new Error('No WhatsApp template name provided');

return recipients.map((recipientPhoneNumber) => {
  const template = {
    name: templateName,
    language: { code: language },
  };

  if (bodyParameters.length) {
    template.components = [
      {
        type: 'body',
        parameters: bodyParameters.map((text) => ({ type: 'text', text })),
      },
    ];
  }

  return {
    json: {
      phoneNumber: recipientPhoneNumber,
      templateName,
      language,
      graphUrl: 'https://graph.facebook.com/v25.0/' + senderPhoneNumberId + '/messages',
      graphRequestBody: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: recipientPhoneNumber,
        type: 'template',
        template,
      },
    },
  };
});

const sentItems = $input.all();
const requestItems = $items('Prepare Meta Template Request');

const errorText = (value) => {
  if (!value) return '';
  if (typeof value === 'string') return value;
  return String(value.message || value.error_user_msg || value.error || JSON.stringify(value));
};

const results = sentItems.map((item, index) => {
  const response = item.json || {};
  const request = requestItems[index]?.json || {};
  const body = response.body || response;
  const message = Array.isArray(body.messages) ? body.messages[0] : null;
  const metaError = body.error || null;
  const ok = Boolean(message && message.id) && !metaError;

  return {
    phoneNumber: request.phoneNumber || '',
    to: request.phoneNumber || '',
    ok,
    status: ok ? (message.message_status || 'accepted') : 'failed',
    metaMessageId: message?.id || '',
    templateName: request.templateName || '',
    messageType: 'template',
    error: ok ? '' : errorText(metaError || body.message || response.message),
    metaError,
    debug: {
      sender: 'meta_http_request',
      graphRequestBody: request.graphRequestBody,
      rawResponse: response,
    },
  };
});

return [{ json: { ok: results.length > 0 && results.every((result) => result.ok), results } }];
